    "ClusterUnit": {
      "enum": [
        "setor_censitario",
        "bairro",
        "zona_eleitoral",
        "secao_eleitoral",
        "district",
        "pontos_de_fluxo",
        "other",
        "none",
        "not_specified"
      ],
      "title": "ClusterUnit",
      "type": "string"
    },
    "PopulationReference": {
      "enum": [
        "census_2022_residents",
        "census_other",
        "tse_eligible",
        "turnout_weighted",
        "mixed",
        "other",
        "not_specified"
      ],
      "title": "PopulationReference",
      "type": "string"
    },
    "PopulationSource": {
      "enum": [
        "tse",
        "ibge",
        "both",
        "other",
        "not_specified"
      ],
      "title": "PopulationSource",
      "type": "string"
    },
    "QuotaDistribution": {
      "description": "One quota dimension with bin labels and percentages.\n\nbin_labels and bin_percentages are parallel arrays. bin_counts is\noptional — populate only if absolute counts per bin are stated.",
      "properties": {
        "variable": {
          "$ref": "#/$defs/QuotaVariable",
          "description": "Which demographic dimension this quota distribution describes."
        },
        "bin_labels": {
          "description": "Exact labels of the bins as written in the text. Examples: ['Masculino', 'Feminino']; ['16 a 24', '25 a 34', '35 a 44', '45 a 59', '60 ou +']; ['Até R$ 2.824,00 (até 2 S.M.)', 'Mais de R$ 2.824,00 a R$ 7.060,00'].",
          "items": {
            "type": "string"
          },
          "title": "Bin Labels",
          "type": "array"
        },
        "bin_percentages": {
          "description": "Percent share of each bin (0-100). Parallel to bin_labels. Example: [50.3, 49.7]. Use empty list if percentages are not stated.",
          "items": {
            "type": "number"
          },
          "title": "Bin Percentages",
          "type": "array"
        },
        "bin_counts": {
          "description": "Absolute respondent count per bin if stated. Parallel to bin_labels. Empty list if not stated. Example: [95, 99, 75, 79, 52].",
          "items": {
            "type": "integer"
          },
          "title": "Bin Counts",
          "type": "array"
        }
      },
      "required": [
        "variable",
        "bin_labels",
        "bin_percentages"
      ],
      "title": "QuotaDistribution",
      "type": "object"
    },
    "QuotaVariable": {
      "enum": [
        "sex",
        "age",
        "education",
        "income",
        "race",
        "religion",
        "occupation",
        "region",
        "other"
      ],
      "title": "QuotaVariable",
      "type": "string"
    },
    "SampleDesignClass": {
      "enum": [
        "simple_random",
        "stratified",
        "quota",
        "multi_stage",
        "ppt",
        "multi_stage_quota",
        "mixed",
        "other",
        "not_specified"
      ],
      "title": "SampleDesignClass",
      "type": "string"
    },
    "SelectionWithinCluster": {
      "enum": [
        "random_walk",
        "quota",
        "pps",
        "convenience",
        "mixed",
        "other",
        "not_specified"
      ],
      "title": "SelectionWithinCluster",
      "type": "string"
    }
  },
  "description": "Sampling design + sample size + quotas + population reference,\nextracted from DS_PLANO_AMOSTRAL + DS_METODOLOGIA_PESQUISA.\n\nv2: dropped the derivable booleans is_probability_sample (derive from\nsample_design_class / selection_within_cluster) and is_quota_sample\n(derive from quota_distributions non-empty), and quota_variables (the\nquota-dimension set = {d.variable for d in quota_distributions}). The\ndev set confirmed quota_variables is ~99.8% redundant: of 536 polls only\n1 named a quota dimension (income) without printing its bins, and that\ncase cannot feed the income-skew lever anyway (no bins → no skew).",
  "properties": {
    "sample_design_class": {
      "$ref": "#/$defs/SampleDesignClass",
      "description": "Overall sampling design family. multi_stage_quota is the Brazilian standard (cluster sample of census tracts + quota selection within); flag distinctly from plain multi_stage or pure quota."
    },
    "sample_design_evidence": {
      "default": "",
      "description": "1-2 sentence quote from the text supporting sample_design_class.",
      "title": "Sample Design Evidence",
      "type": "string"
    },
    "n_stages": {
      "default": 1,
      "description": "Number of sampling stages. Use 3 to mean '3 or more'.",
      "title": "N Stages",
      "type": "integer"
    },
    "stage_descriptions": {
      "description": "Brief description of each stage. Example: ['stage 1: PPT selection of setores censitários', 'stage 2: quota selection within setor by sex/age/education/income'].",
      "items": {
        "type": "string"
      },
      "title": "Stage Descriptions",
      "type": "array"
    },
    "cluster_unit": {
      "$ref": "#/$defs/ClusterUnit",
      "description": "Primary clustering unit (the unit selected at stage 1)."
    },
    "selection_within_cluster": {
      "$ref": "#/$defs/SelectionWithinCluster",
      "description": "How respondents are picked within the cluster."
    },
    "pps_used": {
      "description": "True if probability-proportional-to-size sampling is mentioned anywhere.",
      "title": "Pps Used",
      "type": "boolean"
    },
    "declared_sample_size": {
      "anyOf": [
        {
          "type": "integer"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "Declared n. Null if not stated in the text (also available in QT_ENTREVISTADO).",
      "title": "Declared Sample Size"
    },
    "margin_of_error_pp": {
      "anyOf": [
        {
          "type": "number"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "Margin of error in percentage points (e.g. 4.9 for ±4.9pp). Null if not stated.",
      "title": "Margin Of Error Pp"
    },
    "confidence_level_pct": {
      "anyOf": [
        {
          "type": "number"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "Confidence level percentage (typically 95). Null if not stated.",
      "title": "Confidence Level Pct"
    },
    "population_assumed_for_moe": {
      "default": "",
      "description": "What population assumption underlies the MoE computation, in 1 short phrase. Example: 'amostra aleatória simples', 'população infinita', 'eleitorado de Feijó AC'.",
      "title": "Population Assumed For Moe",
      "type": "string"
    },
    "quota_distributions": {
      "description": "Per-variable distribution. Populate one entry per quota dimension stated with percentages. Skip dimensions where only the variable is named without a distribution.",
      "items": {
        "$ref": "#/$defs/QuotaDistribution"
      },
      "title": "Quota Distributions",
      "type": "array"
    },
    "population_reference": {
      "$ref": "#/$defs/PopulationReference",
      "description": "Which population the quotas are normalized against. census_2022_residents = IBGE 2022 census resident population; tse_eligible = TSE eligible-voter file; turnout_weighted = electorate weighted by expected turnout."
    },
    "population_reference_evidence": {
      "default": "",
      "description": "1-2 sentence quote from the text supporting population_reference.",
      "title": "Population Reference Evidence",
      "type": "string"
    },
    "population_source": {
      "$ref": "#/$defs/PopulationSource",
      "description": "Source(s) cited for population statistics."
    },
