      "description": "True if IBGE setores censitários are explicitly used as clustering or stratification units.",
      "title": "Census Sectors Used",
      "type": "boolean"
    },
    "voter_age_minimum": {
      "anyOf": [
        {
          "type": "integer"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "Minimum voter age in the target population (typically 16). Null if not stated.",
      "title": "Voter Age Minimum"
    },
    "voter_age_maximum": {
      "anyOf": [
        {
          "type": "integer"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "Maximum voter age if explicitly capped (rare). Null if no cap.",
      "title": "Voter Age Maximum"
    },
    "target_population_description": {
      "default": "",
      "description": "1 short phrase describing the target population. Example: 'eleitores residentes de Feijó AC ≥16 anos'.",
      "title": "Target Population Description",
      "type": "string"
    },
    "references_list": {
      "description": "URLs / table references the text cites (IBGE Sidra, TSE SIG, panorama do município, etc). Useful for tracking which pollsters cite which sources.",
      "items": {
        "type": "string"
      },
      "title": "References List",
      "type": "array"
    },
    "text_truncated": {
      "default": false,
      "description": "True if the text appears truncated (hit max_chars cap before sense end).",
      "title": "Text Truncated",
      "type": "boolean"
    },
    "extraction_notes": {
      "default": "",
      "description": "Free-form notes on ambiguity or judgment calls.",
      "title": "Extraction Notes",
      "type": "string"
    }
  },
  "required": [
    "sample_design_class",
    "cluster_unit",
    "selection_within_cluster",
    "pps_used",
    "population_reference",
    "population_source",
    "census_sectors_used"
  ],
  "title": "PollSampling",
  "type": "object"
